# (command, EN, AR)
CHEAT=[('Setup / الإعداد',[
('git --version','Check that Git is installed','تحقق من تثبيت Git'),
('git config --global user.name "Your Name"','Set your name','اضبط اسمك'),
('git config --global user.email "you@example.com"','Set your email (use your GitHub email)','اضبط بريدك (بريد GitHub)'),
('git config --global --list','Show your settings','اعرض إعداداتك')]),
('Start / البداية',[
('git init -b main','Create a repository with branch main','أنشئ مستودعًا بفرع main'),
('git clone URL','Copy a remote repository','انسخ مستودعًا بعيدًا'),
('git status','Show changed, staged and untracked files','اعرض الملفات المتغيرة والمُجهّزة وغير المتتبَّعة')]),
('Snapshot / اللقطات',[
('git add FILE','Stage one file','جهّز ملفًا واحدًا (staging)'),
('git add .','Stage everything in this folder and below','جهّز كل شيء في هذا المجلد وما تحته'),
('git add -A','Stage all changes in the whole repository','جهّز كل التغييرات في المستودع كله'),
('git commit -m "message"','Save a snapshot with a message','احفظ لقطة برسالة'),
('git diff','Show unstaged changes','اعرض التغييرات غير المجهّزة'),
('git diff --staged','Show staged changes','اعرض التغييرات المجهّزة')]),
('History / السجل',[
('git log --oneline','Short history, one line per commit','سجل مختصر، سطر لكل commit'),
('git show COMMIT','Show one commit','اعرض commit واحدًا')]),
('Branches / الفروع',[
('git branch','List local branches','اعرض الفروع المحلية'),
('git switch -c NAME','Create and switch to a branch','أنشئ فرعًا وانتقل إليه'),
('git switch NAME','Switch branch','انتقل إلى فرع'),
('git merge NAME','Merge NAME into the current branch','ادمج NAME في الفرع الحالي'),
('git merge --abort','Cancel a conflicted merge','ألغِ دمجًا متعارضًا'),
('git branch -d NAME','Delete a merged branch','احذف فرعًا مدموجًا')]),
('Remote / البعيد',[
('git remote add origin URL','Connect a remote named origin','اربط remote باسم origin'),
('git remote -v','Show remotes','اعرض الـ remotes'),
('git push -u origin main','First push, set upstream','أول رفع مع ضبط upstream'),
('git push','Push to the upstream','ارفع إلى الـ upstream'),
('git fetch','Download remote changes without merging','نزّل التغييرات البعيدة دون دمج'),
('git pull','Fetch and merge','اجلب وادمج')]),
('Undo / التراجع',[
('git restore FILE','Discard edits in a file (irreversible)','ارمِ تعديلات ملف (لا رجعة)'),
('git restore --staged FILE','Unstage a file','أخرج ملفًا من staging'),
('git stash push -m "msg"','Set edits aside','احفظ التعديلات جانبًا'),
('git stash pop','Bring stashed edits back','أعد التعديلات المخزنة'),
('git commit --amend -m "msg"','Replace the last commit (not pushed)','استبدل آخر commit (قبل الرفع)'),
('git revert COMMIT','Make a commit that cancels another','أنشئ commit يلغي آخر'),
('git reset --soft HEAD~1','Undo last commit, keep staged','ألغِ آخر commit وأبقِ staging'),
('git reflog','Show where HEAD has been','اعرض أماكن HEAD السابقة'),
('git rm --cached FILE','Stop tracking a file, keep it on disk','أوقف تتبع ملف وأبقه على القرص')])]
# (term, EN, AR)
GLOSS=[
('Repository','A project folder tracked by Git, with its history.','مجلد مشروع يتتبعه Git مع تاريخه.'),
('Commit','A saved snapshot of staged changes with a message.','لقطة محفوظة للتغييرات المجهّزة مع رسالة.'),
('Staging area','Where you choose changes for the next commit.','المكان الذي تختار فيه تغييرات الـ commit القادم.'),
('Working directory','The files you see and edit.','الملفات التي تراها وتعدّلها.'),
('Branch','A movable pointer to a commit.','مؤشر متحرك إلى commit.'),
('main','The default branch name in this course.','اسم الفرع الافتراضي في هذا الكورس.'),
('HEAD','Pointer to the branch or commit you are on.','مؤشر إلى الفرع أو الـ commit الذي أنت عليه.'),
('Merge','Combine one branch into another.','دمج فرع في آخر.'),
('Fast-forward','A merge done by moving a branch label ahead.','دمج يتم بتحريك وسم الفرع للأمام.'),
('Merge conflict','Same lines changed differently; you must choose.','تغيير الأسطر نفسها بشكلين؛ عليك الاختيار.'),
('Remote','A copy of the repository hosted elsewhere, such as GitHub.','نسخة من المستودع مستضافة في مكان آخر مثل GitHub.'),
('origin','The default name of the main remote.','الاسم الافتراضي للـ remote الرئيسي.'),
('Upstream','The remote branch your local branch tracks.','الفرع البعيد الذي يتتبعه فرعك المحلي.'),
('Push','Upload local commits to a remote.','رفع commits محلية إلى remote.'),
('Pull','Fetch and merge remote commits.','جلب commits بعيدة ودمجها.'),
('Fetch','Download remote commits without merging.','تنزيل commits بعيدة دون دمج.'),
('Clone','Copy a remote repository to your computer.','نسخ مستودع بعيد إلى جهازك.'),
('Fork','Your own GitHub copy of someone else’s repository.','نسختك على GitHub من مستودع غيرك.'),
('Pull request (PR)','A proposal to merge a branch, with review.','اقتراح لدمج فرع مع مراجعة.'),
('Issue','A task, bug or idea tracked on GitHub.','مهمة أو خطأ أو فكرة تُتابَع في GitHub.'),
('Tracked file','A file Git already knows.','ملف يعرفه Git أصلًا.'),
('Untracked file','A new file Git is not tracking yet.','ملف جديد لا يتتبعه Git بعد.'),
('.gitignore','File listing patterns Git should ignore.','ملف يسرد أنماطًا يتجاهلها Git.'),
('README','File that introduces the project.','ملف يعرّف بالمشروع.'),
('Markdown','Simple text formatting language.','لغة تنسيق نصوص بسيطة.'),
('Stash','Temporary storage for uncommitted edits.','تخزين مؤقت للتعديلات غير المحفوظة.'),
('Revert','Commit that cancels an earlier commit.','commit يلغي commit سابقًا.'),
('Reset','Move a branch to another commit.','نقل فرع إلى commit آخر.'),
('Reflog','Local log of where HEAD has been.','سجل محلي لأماكن HEAD السابقة.'),
('Detached HEAD','HEAD on a commit rather than a branch.','HEAD على commit لا على فرع.'),
('HTTPS','Web protocol used by this course to talk to GitHub.','بروتوكول الويب الذي يستخدمه الكورس مع GitHub.'),
('Git Credential Manager','Windows helper that signs you in to GitHub.','أداة Windows تسجّل دخولك إلى GitHub.'),
('Token','Secret used to authenticate.','سر يُستخدم للمصادقة.'),
('2FA','Second proof of identity at sign-in.','إثبات هوية ثانٍ عند الدخول.'),
('GitHub Pages','Free static hosting from a repository.','استضافة ثابتة مجانية من مستودع.'),
('Source Control','VS Code panel for Git.','لوحة Git في VS Code.'),
('Sync Changes','VS Code button: pull then push.','زر في VS Code: pull ثم push.'),
('Diff','Difference between two versions.','الفرق بين نسختين.'),
('Version control','Recording changes so you can review and restore them.','تسجيل التغييرات لمراجعتها واستعادتها.')]
# (symptom, cause, fix) EN and AR
TROUBLE=[
('“git” is not recognized','Git is not installed or the terminal was opened before installing.','Install Git for Windows, close and reopen Git Bash or VS Code, then run git --version.','«git» غير معروف','Git غير مثبت أو فُتحت الطرفية قبل التثبيت.','ثبّت Git for Windows وأغلق Git Bash أو VS Code وافتحه من جديد ثم نفّذ git --version.'),
('Author identity unknown','user.name and user.email are not set.','Run git config --global user.name "Your Name" and user.email "you@example.com".','Author identity unknown','لم يُضبط user.name وuser.email.','نفّذ git config --global user.name "Your Name" وuser.email "you@example.com".'),
('fatal: not a git repository','You are outside the project folder or never ran git init.','cd into the project folder; run git init if it is a new project.','fatal: not a git repository','أنت خارج مجلد المشروع أو لم تنفّذ git init.','انتقل بـ cd إلى مجلد المشروع، ونفّذ git init إن كان مشروعًا جديدًا.'),
('nothing to commit','No changes, or changes are not staged.','Edit a file or run git add first; check git status.','nothing to commit','لا تغييرات أو لم تُجهَّز.','عدّل ملفًا أو نفّذ git add أولًا وتحقق من git status.'),
('remote origin already exists','You already added origin.','Use git remote -v; fix with git remote set-url origin URL.','remote origin already exists','أضفت origin سابقًا.','استخدم git remote -v وعدّل بـ git remote set-url origin URL.'),
('Repository not found','Wrong URL, or you are signed in to another account.','Check the URL on GitHub; sign in again through Git Credential Manager.','Repository not found','الرابط خاطئ أو دخلت بحساب آخر.','تحقق من الرابط في GitHub وسجّل الدخول من جديد عبر Git Credential Manager.'),
('Authentication failed','Old or wrong saved credentials.','Open Windows Credential Manager, remove github.com entries, then push again and sign in.','Authentication failed','بيانات دخول قديمة أو خاطئة.','افتح Credential Manager في Windows واحذف إدخالات github.com ثم ارفع وسجّل الدخول.'),
('failed to push some refs (fetch first)','GitHub has commits you do not have.','git pull, resolve conflicts if any, then git push.','failed to push some refs (fetch first)','عند GitHub commits لا تملكها.','نفّذ git pull وحلّ التعارضات إن وُجدت ثم git push.'),
('Your local changes would be overwritten','Uncommitted edits block a switch or pull.','Commit or git stash first, then retry.','Your local changes would be overwritten','تعديلات غير محفوظة تمنع التبديل أو السحب.','احفظ commit أو نفّذ git stash ثم أعد المحاولة.'),
('CONFLICT (content)','Two changes touched the same lines.','Edit the file, remove markers, git add, git commit. Or git merge --abort.','CONFLICT (content)','تغييران على الأسطر نفسها.','عدّل الملف وأزل العلامات ثم git add وgit commit. أو git merge --abort.'),
('detached HEAD','You checked out a commit, not a branch.','git switch main, or git switch -c name to keep the work.','detached HEAD','انتقلت إلى commit لا فرع.','git switch main أو git switch -c name للاحتفاظ بالعمل.'),
('Push rejected on main (protected)','The branch is protected.','Push a feature branch and open a pull request.','رفض الرفع إلى main (محمي)','الفرع محمي.','ارفع فرع ميزة وافتح pull request.'),
('I committed a secret','A password or token is in history.','Revoke or rotate it first; then remove it from the code and add it to .gitignore.','حفظت سرًّا في commit','كلمة سر أو token في التاريخ.','ألغِه أو بدّله أولًا ثم أزله من الكود وأضفه إلى .gitignore.'),
('.gitignore does not work','The file was already tracked.','git rm --cached FILE and commit.','.gitignore لا يعمل','الملف مُتتبَّع أصلًا.','git rm --cached FILE ثم commit.'),
('GitHub Pages shows 404','Pages not enabled yet, wrong folder, or no index.html in root.','Settings → Pages: main / root; wait a few minutes; check index.html.','GitHub Pages يعرض 404','لم يُفعَّل أو مجلد خاطئ أو لا index.html في الجذر.','Settings ← Pages: main / root؛ انتظر دقائق؛ تحقق من index.html.'),
('VS Code does not show Source Control changes','Opened the wrong folder.','File → Open Folder and choose the folder that contains .git.','VS Code لا يعرض تغييرات Source Control','فتحت مجلدًا خاطئًا.','File ← Open Folder واختر المجلد الذي فيه .git.')]
